const calcMetrics = (notas: Array<{ valor_total: string; fornecedor?: string; data_nota: string; itens_nota_fiscal: unknown[] }>) => {
    const totalNotas = notas.length;
    const totalValor = notas.reduce(
        (acc, curr) => acc + (parseFloat(curr.valor_total) || 0),
        0,
    );
    const averageValor = totalNotas > 0 ? totalValor / totalNotas : 0;

    const bySupplierMap = new Map<string, number>();
    notas.forEach((nota) => {
        const name = nota.fornecedor || 'Desconhecido';
        bySupplierMap.set(name, (bySupplierMap.get(name) || 0) + (parseFloat(nota.valor_total) || 0));
    });

    const topSuppliers = Array.from(bySupplierMap.entries())
        .map(([name, value]) => ({ name, value }))
        .sort((a, b) => b.value - a.value)
        .slice(0, 5);

    return { totalNotas, totalValor, averageValor, topSuppliers };
};

