47	const calcMetrics = (notas: Array<{ valor_total: string; fornecedor?: string; data_nota: string; itens_nota_fiscal: unknown[] }>) => {
48	    const totalNotas = notas.length;
49	    const totalValor = notas.reduce(
50	        (acc, curr) => acc + (parseFloat(curr.valor_total) || 0),
51	        0,
52	    );
53	    const averageValor = totalNotas > 0 ? totalValor / totalNotas : 0;
54	
55	    const bySupplierMap = new Map<string, number>();
56	    notas.forEach((nota) => {
57	        const name = nota.fornecedor || 'Desconhecido';
58	        bySupplierMap.set(name, (bySupplierMap.get(name) || 0) + (parseFloat(nota.valor_total) || 0));
59	    });
60	
61	    const topSuppliers = Array.from(bySupplierMap.entries())
62	        .map(([name, value]) => ({ name, value }))
63	        .sort((a, b) => b.value - a.value)
64	        .slice(0, 5);
65	
66	    return { totalNotas, totalValor, averageValor, topSuppliers };
67	};
